import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const [, second] = input;
const a = second.split(" ").map(Number);

const count = new Map<number, number>();
for (const x of a) count.set(x, (count.get(x) ?? 0) + 1);

let best = 0;
let bestCount = 0;
for (const [value, c] of count) {
  // 回数が多い、または同じ回数でより小さい値なら更新する
  if (c > bestCount || (c === bestCount && value < best)) {
    best = value;
    bestCount = c;
  }
}
console.log(best);
